//go:build ignore

package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const storeModule = "github.com/usememos/memos/store"

var entityTypes = []string{
	"Attachment",
	"IdentityProvider",
	"Inbox",
	"InstanceSetting",
	"Memo",
	"MemoRelation",
	"MemoShare",
	"Reaction",
	"User",
	"UserIdentity",
	"UserSetting",
}

func isStoreLayerPath(dir string) bool {
	// repo root is cwd
	rel, err := filepath.Rel(".", dir)
	if err != nil {
		return strings.Contains(dir, "/store/")
	}
	rel = filepath.ToSlash(rel)
	return rel == "store" || strings.HasPrefix(rel, "store/")
}

func isTestPackage(name string) bool {
	return strings.HasSuffix(name, "_test")
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax,
		Dir:  "/bench/repo",
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load error: %v\n", err)
		os.Exit(1)
	}
	if packages.PrintErrors(pkgs) > 0 {
		os.Exit(1)
	}

	type refInfo struct {
		withTests    map[string]struct{}
		withoutTests map[string]struct{}
		refs         []string // "pkg:file:line"
	}

	results := make(map[string]*refInfo)
	for _, name := range entityTypes {
		results[name] = &refInfo{
			withTests:    make(map[string]struct{}),
			withoutTests: make(map[string]struct{}),
		}
	}

	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			continue
		}
		if pkg.PkgPath == storeModule {
			continue
		}
		// skip subpackages of store
		if strings.HasPrefix(pkg.PkgPath, storeModule+"/") {
			continue
		}

		// check if any file is under store/
		inStoreLayer := false
		for _, f := range pkg.GoFiles {
			if isStoreLayerPath(filepath.Dir(f)) {
				inStoreLayer = true
				break
			}
		}
		if inStoreLayer {
			continue
		}

		isTest := isTestPackage(pkg.Name)

		for _, file := range pkg.Syntax {
			var inspect func(n ast.Node)
			inspect = func(n ast.Node) {
				if n == nil {
					return
				}
				ast.Inspect(n, func(child ast.Node) bool {
					if child == nil {
						return false
					}
					switch e := child.(type) {
					case *ast.Ident:
						if !e.IsExported() {
							return true
						}
						obj := pkg.TypesInfo.ObjectOf(e)
						if obj == nil {
							return true
						}
						typeName := objName(obj)
						if typeName == "" {
							return true
						}
						for _, ent := range entityTypes {
							if typeName != ent {
								continue
							}
							// verify it's store.Entity
							if !isStoreEntityType(obj, ent) {
								continue
							}
							pos := pkg.Fset.Position(e.Pos())
							pkgKey := pkg.PkgPath
							results[ent].withTests[pkgKey] = struct{}{}
							if !isTest {
								results[ent].withoutTests[pkgKey] = struct{}{}
							}
							rel, _ := filepath.Rel("/bench/repo", pos.Filename)
							results[ent].refs = append(results[ent].refs,
								fmt.Sprintf("%s:%s:%d", pkgKey, rel, pos.Line))
						}
					case *ast.SelectorExpr:
						// handle store.Memo when store is imported
						sel := e.Sel.Name
						for _, ent := range entityTypes {
							if sel != ent {
								continue
							}
							obj := pkg.TypesInfo.ObjectOf(e.Sel)
							if obj == nil {
								continue
							}
							if !isStoreEntityType(obj, ent) {
								continue
							}
							pos := pkg.Fset.Position(e.Pos())
							pkgKey := pkg.PkgPath
							results[ent].withTests[pkgKey] = struct{}{}
							if !isTest {
								results[ent].withoutTests[pkgKey] = struct{}{}
							}
							rel, _ := filepath.Rel("/bench/repo", pos.Filename)
							results[ent].refs = append(results[ent].refs,
								fmt.Sprintf("%s:%s:%d", pkgKey, rel, pos.Line))
						}
					}
					return true
				})
			}
			inspect(file)
		}
	}

	type row struct {
		name         string
		withTests    int
		withoutTests int
		pkgs         []string
		pkgsNoTest   []string
	}
	var rows []row
	for _, ent := range entityTypes {
		r := results[ent]
		pkgs := sortedKeys(r.withTests)
		pkgsNoTest := sortedKeys(r.withoutTests)
		rows = append(rows, row{ent, len(pkgs), len(pkgsNoTest), pkgs, pkgsNoTest})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].withoutTests != rows[j].withoutTests {
			return rows[i].withoutTests > rows[j].withoutTests
		}
		return rows[i].withTests > rows[j].withTests
	})

	fmt.Println("=== RANKING (non-test packages) ===")
	for _, r := range rows {
		fmt.Printf("%s: %d pkgs (with tests: %d)\n", r.name, r.withoutTests, r.withTests)
		fmt.Printf("  pkgs: %s\n", strings.Join(r.pkgsNoTest, ", "))
	}

	fmt.Println("\n=== TOP 2 DETAIL ===")
	for i := 0; i < 2 && i < len(rows); i++ {
		r := rows[i]
		fmt.Printf("\n#%d %s — %d non-test pkgs, %d with-test pkgs\n", i+1, r.name, r.withoutTests, r.withTests)
		fmt.Println("Non-test packages:")
		for _, p := range r.pkgsNoTest {
			fmt.Println(" ", p)
		}
	}

	// Also find definition lines
	fmt.Println("\n=== DEFINITIONS ===")
	for _, ent := range entityTypes {
		for _, pkg := range pkgs {
			if pkg.PkgPath != storeModule {
				continue
			}
			scope := pkg.Types.Scope()
			obj := scope.Lookup(ent)
			if obj == nil {
				continue
			}
			pos := pkg.Fset.Position(obj.Pos())
			rel, _ := filepath.Rel("/bench/repo", pos.Filename)
			fmt.Printf("%s: %s:%d\n", ent, rel, pos.Line)
		}
	}
}

func objName(obj types.Object) string {
	switch o := obj.(type) {
	case *types.TypeName:
		return o.Name()
	case *types.Var:
		if named, ok := o.Type().(*types.Named); ok {
			return named.Obj().Name()
		}
	case *types.Const:
		if named, ok := o.Type().(*types.Named); ok {
			return named.Obj().Name()
		}
	}
	return ""
}

func isStoreEntityType(obj types.Object, entityName string) bool {
	var named *types.Named
	switch o := obj.(type) {
	case *types.TypeName:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	case *types.Var, *types.Const, *types.Func:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	case *types.PkgName:
		return false
	}
	if named == nil {
		return false
	}
	if named.Obj().Name() != entityName {
		return false
	}
	pkg := named.Obj().Pkg()
	if pkg == nil {
		return false
	}
	return pkg.Path() == storeModule
}

func sortedKeys(m map[string]struct{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
EOF
cd /bench/repo && go run /tmp/analyze_refs.go 2>&1

