    my %aliases;
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $base = (split /\//, $path)[-1];
        $aliases{$path} = $base;
    }
    while ($content =~ /import\s*\((.*?)\)/gs) {
