    my $ent = $ranking[$idx];
    my $nt = scalar keys %{$refs_no{$ent}};
    my $wt = scalar keys %{$refs_with{$ent}};
    my ($f, $ln) = @{$DEFINITIONS{$ent}};
    print "\n#" . ($idx+1) . " $ent\n";
    print "  Definition: $f:$ln\n";
