    my $store_alias = $aliases->{$STORE_MODULE};
    next unless defined $store_alias;

    my $pkg_path = package_path_from_dir(dirname($path));
    my $pkg_name = go_package_name($content);
    my $is_test = ($path =~ /_test\.go$/) || (defined $pkg_name && $pkg_name =~ /_test$/);
    my $rel_path = $path;
    $rel_path =~ s/^\Q$REPO\E\/?//;

    my $i = 0;
    for my $line (split /\n/, $content) {
        $i++;
        for my $ent (@ENTITY_TYPES) {
            next unless $line =~ /\b\Q$store_alias\E\.\Q$ent\E\b/;
            $refs_with{$ent}{$pkg_path}{"$rel_path:$i"} = 1;
            $refs_no{$ent}{$pkg_path}{"$rel_path:$i"} = 1 unless $is_test;
        }
    }
}

