//go:build ignore

package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const storeModule = "github.com/usememos/memos/store"

var entityTypes = []string{
	"Attachment",
	"IdentityProvider",
	"Inbox",
	"InstanceSetting",
	"Memo",
	"MemoRelation",
	"MemoShare",
	"Reaction",
	"User",
	"UserIdentity",
	"UserSetting",
}

var definitions = map[string][2]interface{}{
	"Attachment":       {"store/attachment.go", 16},
	"IdentityProvider": {"store/idp.go", 12},
	"Inbox":            {"store/inbox.go", 24},
	"InstanceSetting":  {"store/instance_setting.go", 14},
	"Memo":             {"store/memo.go", 35},
	"MemoRelation":     {"store/memo_relation.go", 16},
	"MemoShare":        {"store/memo_share.go", 6},
	"Reaction":         {"store/reaction.go", 7},
	"User":             {"store/user.go", 29},
	"UserIdentity":     {"store/user_identity.go", 8},
	"UserSetting":      {"store/user_setting.go", 13},
}

func isStoreLayerPkg(pkgPath string) bool {
	return pkgPath == storeModule || strings.HasPrefix(pkgPath, storeModule+"/")
}

func isTestPackage(pkgPath, pkgName string) bool {
	if strings.HasSuffix(pkgName, "_test") {
		return true
	}
	// Integration test packages live under .../test
	if strings.HasSuffix(pkgPath, "/test") || strings.Contains(pkgPath, "/test/") {
		return true
	}
	return false
}

func isStoreEntity(obj types.Object, entityName string) bool {
	var named *types.Named
	switch o := obj.(type) {
	case *types.TypeName:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	case *types.Var, *types.Const, *types.Func:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	}
	if named == nil {
		return false
	}
	if named.Obj().Name() != entityName {
		return false
	}
	pkg := named.Obj().Pkg()
	return pkg != nil && pkg.Path() == storeModule
}

func recordRef(entity string, pkgPath string, isTest bool, refs map[string]map[string]struct{}, withTest map[string]map[string]struct{}, loc string) {
	if withTest[entity] == nil {
		withTest[entity] = map[string]struct{}{}
	}
	withTest[entity][pkgPath] = struct{}{}
	if !isTest {
		if refs[entity] == nil {
			refs[entity] = map[string]struct{}{}
		}
		refs[entity][pkgPath] = struct{}{}
	}
}

func inspectNode(pkg *packages.Package, n ast.Node, entity string, isTest bool, refs, withTest map[string]map[string]struct{}, loc func() string) {
	switch e := n.(type) {
	case *ast.Ident:
		if !e.IsExported() && e.Name != entity {
			return
		}
		obj := pkg.TypesInfo.ObjectOf(e)
		if obj == nil || !isStoreEntity(obj, entity) {
			return
		}
		recordRef(entity, pkg.PkgPath, isTest, refs, withTest, loc())
	case *ast.SelectorExpr:
		obj := pkg.TypesInfo.ObjectOf(e.Sel)
		if obj == nil || !isStoreEntity(obj, entity) {
			return
		}
		recordRef(entity, pkg.PkgPath, isTest, refs, withTest, loc())
	}
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax,
		Dir: "/bench/repo",
	}

	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load: %v\n", err)
		os.Exit(1)
	}
	if packages.PrintErrors(pkgs) > 0 {
		os.Exit(1)
	}

	refs := make(map[string]map[string]struct{})
	withTest := make(map[string]map[string]struct{})

	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 || isStoreLayerPkg(pkg.PkgPath) {
			continue
		}
		isTest := isTestPackage(pkg.PkgPath, pkg.Name)

		for _, file := range pkg.Syntax {
			filename := pkg.Fset.File(file.Pos()).Name()
			ast.Inspect(file, func(n ast.Node) bool {
				if n == nil {
					return false
				}
				pos := pkg.Fset.Position(n.Pos())
				rel, _ := filepath.Rel("/bench/repo", pos.Filename)
				loc := func() string { return fmt.Sprintf("%s:%s:%d", pkg.PkgPath, rel, pos.Line) }
				for _, entity := range entityTypes {
					inspectNode(pkg, n, entity, isTest, refs, withTest, loc)
				}
				return true
			})
			_ = filename
		}
	}

	type row struct {
		name         string
		nonTest      int
		withTest     int
		nonTestPkgs  []string
		withTestPkgs []string
	}
	var rows []row
	for _, ent := range entityTypes {
		nt := sortedKeys(refs[ent])
		wt := sortedKeys(withTest[ent])
		rows = append(rows, row{ent, len(nt), len(wt), nt, wt})
	}
	sort.Slice(rows, func(i, j int) bool {
		if rows[i].nonTest != rows[j].nonTest {
			return rows[i].nonTest > rows[j].nonTest
		}
		if rows[i].withTest != rows[j].withTest {
			return rows[i].withTest > rows[j].withTest
		}
		return rows[i].name < rows[j].name
	})

	fmt.Println("=== TYPE-AWARE RANKING (go/types, non-test packages) ===")
	for _, r := range rows {
		def := definitions[r.name]
		fmt.Printf("%s: %d non-test / %d with-test — %v:%v\n", r.name, r.nonTest, r.withTest, def[0], def[1])
		for _, p := range r.nonTestPkgs {
			fmt.Printf("  %s\n", p)
		}
	}

	fmt.Println("\n=== TOP 2 ===")
	for i := 0; i < 2 && i < len(rows); i++ {
		r := rows[i]
		def := definitions[r.name]
		fmt.Printf("\n#%d %s\n", i+1, r.name)
		fmt.Printf("  Definition: %v:%v\n", def[0], def[1])
		fmt.Printf("  Non-test package count: %d\n", r.nonTest)
		fmt.Printf("  With-test package count: %d\n", r.withTest)
		fmt.Println("  Non-test packages:")
		for _, p := range r.nonTestPkgs {
			fmt.Printf("    %s\n", p)
		}
	}

	fmt.Println("\n=== DEFINITIONS (from types scope) ===")
	for _, ent := range entityTypes {
		for _, pkg := range pkgs {
			if pkg.PkgPath != storeModule {
				continue
			}
			obj := pkg.Types.Scope().Lookup(ent)
			if obj == nil {
				continue
			}
			pos := pkg.Fset.Position(obj.Pos())
			rel, _ := filepath.Rel("/bench/repo", pos.Filename)
			fmt.Printf("%s: %s:%d\n", ent, rel, pos.Line)
		}
	}
}

func sortedKeys(m map[string]struct{}) []string {
	if m == nil {
		return nil
	}
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

