package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

const storeModule = "github.com/usememos/memos/store"

var entityTypes = []string{"User", "Memo"}

func isStoreLayerPkg(pkgPath string) bool {
	return pkgPath == storeModule || strings.HasPrefix(pkgPath, storeModule+"/")
}

func isTestPackage(pkgPath, pkgName string) bool {
	if strings.HasSuffix(pkgName, "_test") {
		return true
	}
	if strings.HasSuffix(pkgPath, "/test") || strings.Contains(pkgPath, "/test/") {
		return true
	}
	return false
}

func isStoreEntity(obj types.Object, entityName string) bool {
	var named *types.Named
	switch o := obj.(type) {
	case *types.TypeName:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	case *types.Var, *types.Const, *types.Func:
		if tn, ok := o.Type().(*types.Named); ok {
			named = tn
		}
	}
	if named == nil {
		return false
	}
	if named.Obj().Name() != entityName {
		return false
	}
	pkg := named.Obj().Pkg()
	return pkg != nil && pkg.Path() == storeModule
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles |
			packages.NeedImports | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax,
		Dir: "/bench/repo",
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}

	type site struct {
		pkg, file string
		line      int
		isTest    bool
	}
	sites := map[string][]site{}

	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 || isStoreLayerPkg(pkg.PkgPath) {
			continue
		}
		isTest := isTestPackage(pkg.PkgPath, pkg.Name)
		for _, file := range pkg.Syntax {
			ast.Inspect(file, func(n ast.Node) bool {
				if n == nil {
					return false
				}
				sel, ok := n.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				for _, ent := range entityTypes {
					if sel.Sel.Name != ent {
						continue
					}
					obj := pkg.TypesInfo.ObjectOf(sel.Sel)
					if obj == nil || !isStoreEntity(obj, ent) {
						continue
					}
					pos := pkg.Fset.Position(sel.Pos())
					rel, _ := filepath.Rel("/bench/repo", pos.Filename)
					sites[ent] = append(sites[ent], site{pkg.PkgPath, rel, pos.Line, isTest})
				}
				return true
			})
		}
	}

	for _, ent := range entityTypes {
		fmt.Printf("=== %s reference sites ===\n", ent)
		byPkg := map[string][]site{}
		for _, s := range sites[ent] {
			byPkg[s.pkg] = append(byPkg[s.pkg], s)
		}
		pkgs := make([]string, 0, len(byPkg))
		for p := range byPkg {
			pkgs = append(pkgs, p)
		}
		sort.Strings(pkgs)
		for _, p := range pkgs {
			testFlag := ""
			if byPkg[p][0].isTest {
				testFlag = " [TEST PKG]"
			}
			fmt.Printf("%s%s\n", p, testFlag)
			seen := map[string]struct{}{}
			for _, s := range byPkg[p] {
				key := fmt.Sprintf("%s:%d", s.file, s.line)
				if _, ok := seen[key]; ok {
					continue
				}
				seen[key] = struct{}{}
				fmt.Printf("  %s:%d\n", s.file, s.line)
				if len(seen) >= 4 {
					break
				}
			}
			if len(byPkg[p]) > 4 {
				fmt.Printf("  ... %d total sites\n", len(byPkg[p]))
			}
		}
	}
}
GOEOF
